def dissect_square():
    # Define the size of the square
    size = 10

    # Define the number of rectangles
    num_rectangles = 14

    # Create a 10x10 grid to represent the square
    grid = [[0 for _ in range(size)] for _ in range(size)]

    # Define the positions of the rectangles
    for i in range(num_rectangles):
        if i < 4:
            x = i
            for j in range(size):
                grid[0][j] = x
        elif i < 7:
            x = i - 4
            for j in range(x, size):
                grid[j][0] = x
        elif i < 9:
            x = i - 7
            for j in range(x, size):
                grid[j][size - 1] = x
        else:
            x = i - 9
            for j in range(size):
                grid[size - 1][j] = x

    return grid

grid = dissect_square()
